+  await page.keyboard.press("Enter");
+  await expect(ruleCell.locator(".cm-content")).toBeVisible();
+
+  await page.keyboard.press("Escape");
+  await expect(ruleCell.locator(".cm-content")).toHaveCount(0);
+
